    let mut ry: [[f64; 3]; 3] = [[crate::pm::cos(xp), 0.0, crate::pm::sin(xp)], [0.0, 1.0, 0.0], [(-(crate::pm::sin(xp))), 0.0, crate::pm::cos(xp)]];
