/// The decimal year of a Julian date.
/// - jd: real[1] (passed a plain number)
/// - returns y: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn decyear(jd: f64) -> f64 {
    let mut y: f64 = 0.0;
    y = (2000.0 + ((jd - 2451544.5) / 365.25));
    y
}

/// x reduced to [0, 360).
/// - x: real[1] (passed a plain number)
/// - returns y: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn mod360(x: f64) -> f64 {
    let mut y: f64 = 0.0;
    y = crate::pm::fmod(x, 360.0);
    if (y < 0.0) {
        y = (y + 360.0);
    }
    y
}

