    let mut a: [f64; 3] = [((crate::pm::cos(z) * sm[0]) + (crate::pm::sin(z) * sm[1])), (((-(crate::pm::sin(z))) * sm[0]) + (crate::pm::cos(z) * sm[1])), sm[2]];
    let mut b: [f64; 3] = [((crate::pm::cos((-(th))) * a[0]) - (crate::pm::sin((-(th))) * a[2])), a[1], ((crate::pm::sin((-(th))) * a[0]) + (crate::pm::cos((-(th))) * a[2]))];
