                let mut k2: f64 = crate::pm::sqrt((((((n as f64) - 1.0) * ((n as f64) - 1.0)) - ((m as f64) * (m as f64))) / (((n as f64) * (n as f64)) - ((m as f64) * (m as f64)))));
