/// The field [T] at an inertial position at a Julian date and Earth orientation eop: to the Earth-fixed frame, geodetic
/// coordinates, IGRF in north-east-down, back to J2000.
/// - r_eci: real[m][3] (passed in m)
/// - jd: real[1] (passed a plain number)
/// - eop: real[1][3] (passed a plain number)
/// - gh: real[1][195] (passed a plain number)
/// - nmax: int (passed a whole number)
/// - returns b: real[1][3] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn field_eci(r_eci: [f64; 3], jd: f64, eop: [f64; 3], gh: [f64; 195], nmax: i64) -> [f64; 3] {
    let mut b: [f64; 3] = [0.0; 3];
    let mut c: [[f64; 3]; 3] = crate::gen::frames::eci2ecef(jd, eop);
    let mut re: [f64; 3] = rt::mv(c, r_eci);
    let (mut lat, mut lon, mut h) = crate::gen::frames::geodetic(re);
    let mut bn: [f64; 3] = crate::gen::frames::igrf_ned(gh, lat, lon, (h / 1000.0), nmax);
    bn[0] = (bn[0] * 1.0e-9);
    bn[1] = (bn[1] * 1.0e-9);
    bn[2] = (bn[2] * 1.0e-9);
    let mut sl: f64 = crate::pm::sin(lat);
    let mut cl: f64 = crate::pm::cos(lat);
    let mut so: f64 = crate::pm::sin(lon);
    let mut co: f64 = crate::pm::cos(lon);
    let mut be: [f64; 3] = [(((((-(sl)) * co) * bn[0]) - (so * bn[1])) - ((cl * co) * bn[2])), (((((-(sl)) * so) * bn[0]) + (co * bn[1])) - ((cl * so) * bn[2])), ((cl * bn[0]) - (sl * bn[2]))];
    b = crate::gen::math::mat3t_vec(c, be);
    b
}
